import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const TITANS=[
 {name:'Godzilla 2014',kind:'godzilla',color:0x303d43,glow:0x327a8e,size:1.04,hp:145,power:1.2,speed:5.4},
 {name:'Godzilla 2019',kind:'godzilla',color:0x35434a,glow:0x4ab6cf,size:1.12,hp:160,power:1.25,speed:5.1},
 {name:'Godzilla 2021',kind:'godzilla',color:0x39464b,glow:0x68c8d3,size:1.16,hp:155,power:1.2,speed:5.5},
 {name:'Godzilla Evolved',kind:'evolved',color:0x282e39,glow:0xf071a3,size:1.13,hp:150,power:1.48,speed:6.5},
 {name:'King Kong 2017',kind:'kong',color:0x705039,glow:0xe98e51,size:.96,hp:135,power:1.2,speed:6.8},
 {name:'King Kong 2021',kind:'kong',color:0x66503e,glow:0xf4a36a,size:1.02,hp:150,power:1.3,speed:6.6},
 {name:'King Kong 2024',kind:'kong',color:0x79614b,glow:0xef8457,size:1.05,hp:155,power:1.38,speed:7.1},
 {name:'Mechagodzilla',kind:'mecha',color:0x59666a,glow:0xff384b,size:1.14,hp:180,power:1.42,speed:6.3},
 {name:'King Ghidorah',kind:'ghidorah',color:0x98713e,glow:0xf8ce68,size:1.2,hp:175,power:1.35,speed:6.2},
 {name:'Rodan',kind:'rodan',color:0x593b35,glow:0xff7048,size:.94,hp:120,power:1.2,speed:8.2},
 {name:'Mothra',kind:'mothra',color:0xdec99d,glow:0x74d9d4,size:.87,hp:125,power:1.2,speed:7.4},
 {name:'Shimo',kind:'shimo',color:0xa8c6c7,glow:0x9feafa,size:1.18,hp:190,power:1.3,speed:5.6},
 {name:'Scylla',kind:'scylla',color:0x693e3b,glow:0xef6c4a,size:.93,hp:135,power:1.18,speed:6.3},
 {name:'Tiamat',kind:'tiamat',color:0x397b83,glow:0x65e5e2,size:1.05,hp:160,power:1.3,speed:7.0}
];
const $=s=>document.querySelector(s), scene=new THREE.Scene();
scene.background=new THREE.Color(0x101a22); scene.fog=new THREE.FogExp2(0x16222a,.0085);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,700); camera.position.set(0,14,30);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'}); renderer.setSize(innerWidth,innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.18; $('#game').appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0x9db5c4,0x26302e,1.45));
const moon=new THREE.DirectionalLight(0xd0e0e9,2.4); moon.position.set(-35,70,30); moon.castShadow=true; moon.shadow.mapSize.set(2048,2048); moon.shadow.camera.left=-100; moon.shadow.camera.right=100; moon.shadow.camera.top=100; moon.shadow.camera.bottom=-100; scene.add(moon);
const rim=new THREE.DirectionalLight(0x36879b,1.7); rim.position.set(40,25,-35); scene.add(rim);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const groundMat=mat(0x222c30,.94), roadMat=mat(0x151d22,.92), steelMat=mat(0x47535a,.6,.65), rubbleMat=mat(0x64635d,1);
const floor=new THREE.Mesh(new THREE.PlaneGeometry(460,460),groundMat); floor.rotation.x=-Math.PI/2; floor.position.y=-.12; floor.receiveShadow=true; scene.add(floor);
// Harbor and the midnight city grid.
const water=new THREE.Mesh(new THREE.PlaneGeometry(360,110),new THREE.MeshStandardMaterial({color:0x173846,roughness:.34,metalness:.42})); water.rotation.x=-Math.PI/2;water.position.set(0,-.17,-150);scene.add(water);
const grid=new THREE.GridHelper(400,80,0x35444a,0x29383e);grid.position.y=-.1;grid.material.transparent=true;grid.material.opacity=.28;scene.add(grid);
for(let r=-2;r<=2;r++)for(let c=-2;c<=2;c++){let x=c*44,z=r*44;if(Math.abs(x)<18||Math.abs(z)<18)continue;let road=new THREE.Mesh(new THREE.PlaneGeometry(12,44),roadMat);road.rotation.x=-Math.PI/2;road.position.set(x,0,z);road.receiveShadow=true;scene.add(road);let road2=new THREE.Mesh(new THREE.PlaneGeometry(44,12),roadMat);road2.rotation.x=-Math.PI/2;road2.position.set(x,0,z);road2.receiveShadow=true;scene.add(road2);}
// Shared luminous window facade, repeated across hand-built towers.
function windowTexture(seed){const c=document.createElement('canvas');c.width=128;c.height=256;const x=c.getContext('2d');x.fillStyle='#26363d';x.fillRect(0,0,128,256);let n=seed;const rand=()=>((n=(n*1664525+1013904223)>>>0)/4294967296);for(let y=5;y<256;y+=12)for(let xx=5;xx<128;xx+=10){x.fillStyle=rand()>.42?(rand()>.5?'#b9a875':'#d18b5f'):'#17262d';x.globalAlpha=.22+rand()*.65;x.fillRect(xx,y,5,7);}x.globalAlpha=1;const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;return t;}
let buildings=[];const buildingRoot=new THREE.Group();scene.add(buildingRoot);let seed=79;const rnd=()=>((seed=(seed*1664525+1013904223)>>>0)/4294967296);
function addBuilding(x,z,w,d,h,custom=false){const tex=windowTexture(seed);let m=new THREE.MeshStandardMaterial({map:tex,color:0x9daeb2,roughness:.82,metalness:.12});let body=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);body.position.set(x,h/2,z);body.castShadow=true;body.receiveShadow=true;buildingRoot.add(body);let roof=new THREE.Mesh(new THREE.BoxGeometry(w+1,.7,d+1),mat(0x424e52,.65,.3));roof.position.set(x,h+.35,z);roof.castShadow=true;buildingRoot.add(roof);let top=new THREE.Mesh(new THREE.BoxGeometry(w*.22,Math.max(1,h*.07),d*.22),steelMat);top.position.set(x,h+.7+Math.max(1,h*.035),z);top.castShadow=true;buildingRoot.add(top);let obj={x,z,w,d,h,hp:100,body,roof,top,dead:false};buildings.push(obj);return obj;}
// Dense near blocks, distant skyline silhouettes.
for(let i=0;i<80;i++){let x=(rnd()-.5)*190,z=(rnd()-.5)*190;if(Math.abs(x)<18&&Math.abs(z)<18)continue;let w=8+rnd()*9,d=8+rnd()*9,h=15+rnd()*75;if(Math.abs(x)>75||Math.abs(z)>75)h*=1.35;addBuilding(x,z,w,d,h);}
// waterfront towers frame the central play space
for(let i=0;i<8;i++){let x=(i-3.5)*22;addBuilding(x,-83,13,16,50+rnd()*65);}
// Street lamps / tiny vehicles / road paint.
const lampMat=new THREE.MeshStandardMaterial({color:0xffd18c,emissive:0xffa642,emissiveIntensity:2});
for(let i=0;i<24;i++){let x=(i%6-2.5)*40,z=(Math.floor(i/6)-1.5)*42;let pole=new THREE.Mesh(new THREE.CylinderGeometry(.13,.21,5,6),steelMat);pole.position.set(x,2.5,z);scene.add(pole);let arm=new THREE.Mesh(new THREE.BoxGeometry(1.7,.12,.16),steelMat);arm.position.set(x+.7,4.7,z);scene.add(arm);let bulb=new THREE.Mesh(new THREE.SphereGeometry(.23,8,6),lampMat);bulb.position.set(x+1.35,4.6,z);scene.add(bulb);}
const vehicleMats=[0x283b45,0x99805d,0x743e38,0x9aa3a3].map(c=>mat(c,.48,.35));
for(let i=0;i<18;i++){let car=new THREE.Group();let body=new THREE.Mesh(new THREE.BoxGeometry(2.2,.9,4),vehicleMats[i%4]);body.position.y=.7;body.castShadow=true;car.add(body);let cab=new THREE.Mesh(new THREE.BoxGeometry(1.7,.7,1.8),mat(0x37484e,.34,.3));cab.position.set(0,1.35,-.1);car.add(cab);for(let sx of [-.9,.9])for(let sz of [-1.25,1.25]){let wh=new THREE.Mesh(new THREE.CylinderGeometry(.34,.34,.22,10),mat(0x111618));wh.rotation.z=Math.PI/2;wh.position.set(sx,.4,sz);car.add(wh);}car.position.set((rnd()-.5)*100,.0,(rnd()-.5)*100);car.rotation.y=rnd()*Math.PI;scene.add(car);car.userData={wrecked:false};vehicles.push(car);}

