const v3=(x,y,z)=>new THREE.Vector3(x,y,z), sphereG=new THREE.SphereGeometry(1,14,10), boxG=new THREE.BoxGeometry(1,1,1), capsuleG=new THREE.CapsuleGeometry(.7,1.2,4,8);
function blob(parent,geo,material,pos,scale,rot){let m=new THREE.Mesh(geo,material);m.position.set(...pos);m.scale.set(...scale);if(rot)m.rotation.set(...rot);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function link(parent,a,b,r,material){let mid=v3((a[0]+b[0])/2,(a[1]+b[1])/2,(a[2]+b[2])/2),dir=v3(b[0]-a[0],b[1]-a[1],b[2]-a[2]);let m=new THREE.Mesh(new THREE.CylinderGeometry(r*.78,r,dir.length(),8),material);m.position.copy(mid);m.quaternion.setFromUnitVectors(v3(0,1,0),dir.normalize());m.castShadow=true;parent.add(m);return m;}
class Titan{
 constructor(spec,player=false){this.spec=spec;this.player=player;this.group=new THREE.Group();this.group.scale.setScalar(spec.size);this.group.position.set(player?0:10,0,player?0:-17);scene.add(this.group);this.health=spec.hp;this.maxHealth=spec.hp;this.energy=100;this.phase=Math.random()*6;this.action='idle';this.actionTime=0;this.stun=0;this.velocity=v3(0,0,0);this.dead=false;this.target=null;this.build();}
 build(){let s=this.spec,k=s.kind;this.skin=mat(s.color,.85,k==='mecha'?.45:.03);this.dark=mat(new THREE.Color(s.color).multiplyScalar(.55),.9);this.glowMat=new THREE.MeshStandardMaterial({color:s.glow,emissive:s.glow,emissiveIntensity:2,roughness:.4});let g=this.group;
 // Shared mass anatomy with variant-specific silhouette details and material language.
 this.torso=blob(g,sphereG,this.skin,[0,3.8,0],[1.18,1.65,.72]);blob(g,sphereG,this.skin,[0,5.25,.04],[.76,.86,.65]);this.head=blob(g,sphereG,this.skin,[0,6.12,-.05],[.55,.55,.55]);blob(g,sphereG,this.dark,[0,5.9,-.47],[.42,.15,.24]);
 this.eyes=[];for(let side of [-1,1])this.eyes.push(blob(g,sphereG,this.glowMat,[side*.29,6.22,-.47],[.075,.065,.06]));
 this.arms=[];this.legs=[];for(let side of [-1,1]){let shoulder=blob(g,sphereG,this.skin,[side*1,4.7,0],[.57,.62,.56]);let arm=new THREE.Group();arm.position.set(side*1.12,4.42,-.01);g.add(arm);link(arm,[0,0,0],[side*.12,-1.02,-.05],.32,this.skin);blob(arm,sphereG,this.skin,[side*.12,-1.06,-.07],[.42,.48,.42]);blob(arm,sphereG,this.skin,[side*.18,-1.47,-.25],[.38,.22,.35]);for(let c=0;c<3;c++)link(arm,[side*.12+c*.1,-1.5,-.4],[side*.15+c*.13,-1.75,-.53],.07,this.dark);this.arms.push(arm);
 let leg=new THREE.Group();leg.position.set(side*.55,2.85,.02);g.add(leg);blob(leg,sphereG,this.skin,[0,-.55,0],[.49,.95,.53]);blob(leg,sphereG,this.skin,[0,-1.18,-.22],[.52,.25,.78]);this.legs.push(leg);}
 this.tail=new THREE.Group();this.tail.position.set(0,3.45,.52);g.add(this.tail);let prev=[0,0,0];for(let i=0;i<5;i++){let p=[i%2===0?.1:-.1,-.05*(i+1),.72*(i+1)];link(this.tail,prev,p,.42-i*.062,this.skin);prev=p;}blob(this.tail,sphereG,this.skin,prev,[.17,.19,.3]);
 this.plates=[];if(['godzilla','evolved','shimo','scylla','tiamat','mecha'].includes(k)){let n=k==='evolved'?8:6;for(let i=0;i<n;i++){let z=-.82+i*.39,y=5.5-i*.36,wide=(i%2===0?.65:.47);let plate=blob(g,new THREE.ConeGeometry(.52,1.08,5),k==='godzilla'||k==='evolved'?this.glowMat:this.dark,[0,y,z],[wide,1, .32],[.08,0,0]);plate.rotation.z=Math.PI;this.plates.push(plate);}}
 if(k==='kong'){blob(g,sphereG,this.dark,[0,4.7,.12],[.85,.5,.75]);this.axe=new THREE.Group();this.axe.position.set(.9,3.4,-.08);g.add(this.axe);link(this.axe,[0,.2,0],[.05,1.25,0],.09,mat(0x684832));let blade=blob(this.axe,new THREE.BoxGeometry(1,.68,.14),this.glowMat,[.38,1.28,0],[1,1,1],[0,0,-.26]);this.axe.visible=false;}
 if(k==='ghidorah'){for(let side of [-1,1]){link(g,[side*.32,5.9,-.2],[side*.75,7.2,-.25],.2,this.skin);blob(g,new THREE.ConeGeometry(.22,.7,7),this.glowMat,[side*.75,7.57,-.25],[1,1,1],[0,0,side*.3]);}this.wings=[];for(let side of [-1,1])this.wings.push(blob(g,new THREE.ConeGeometry(1.7,2.3,4),this.skin,[side*1.65,4.55,.4],[1,.8,.24],[0,0,-side*.6]));}
 if(k==='rodan'||k==='mothra'){this.wings=[];for(let side of [-1,1]){let wing=blob(g,new THREE.ConeGeometry(2.2,2.5,5),k==='mothra'?this.glowMat:this.skin,[side*1.55,4.5,.1],[1,.8,.17],[0,0,-side*.65]);this.wings.push(wing);}}
 if(k==='mecha'){for(let side of [-1,1]){blob(g,boxG,steelMat,[side*1,4.5,0],[.48,.76,.55]);blob(g,sphereG,this.glowMat,[side*.45,6.2,-.47],[.08,.07,.07]);}}
 if(k==='shimo'){for(let i=0;i<9;i++)blob(g,new THREE.ConeGeometry(.17,.55,4),this.glowMat,[Math.sin(i)*.78,4.5+i*.15,.35],[1,1,1],[0,0,Math.sin(i)*.7]);}
 this.horns=[];if(k==='scylla'){for(let x of [-.85,-.35,.35,.85])this.horns.push(blob(g,new THREE.ConeGeometry(.13,.75,5),this.dark,[x,4.8,.4],[1,1,1],[.5,0,x*.4]));}
 }
 update(dt){this.phase+=dt*(this.action==='run'?8:this.action==='walk'?4:1.6);if(this.actionTime>0){this.actionTime-=dt;if(this.actionTime<=0&&this.action!=='stunned')this.action='idle';}if(this.stun>0){this.stun-=dt;this.action='stunned';}else if(this.action==='stunned'&&this.actionTime<=0)this.action='idle';
 let moving=Math.hypot(this.velocity.x,this.velocity.z)>.22;for(let i=0;i<this.legs.length;i++)this.legs[i].rotation.x=moving?Math.sin(this.phase+i*Math.PI)*.52:Math.sin(this.phase+i)*.035;for(let i=0;i<this.arms.length;i++){let arm=this.arms[i];arm.rotation.x=moving?Math.sin(this.phase+i*Math.PI+Math.PI)*.32:Math.sin(this.phase+i)*.04;arm.rotation.z=(i===0?1:-1)*.05;if(this.action==='light'&&i===0)arm.rotation.x=-1.05;if(this.action==='heavy'&&i===1)arm.rotation.x=-1.5;if(this.action==='roar')arm.rotation.x=-.5;}
 this.tail.rotation.x=Math.sin(this.phase*.5)*.11;this.tail.rotation.y=Math.sin(this.phase*.7)*.23;if(this.action==='stunned'){this.group.rotation.z=THREE.MathUtils.damp(this.group.rotation.z,(this.velocity.x>0?-.3:.3),3,dt);}else this.group.rotation.z=THREE.MathUtils.damp(this.group.rotation.z,0,3,dt);
 if(this.wings)for(let i=0;i<this.wings.length;i++)this.wings[i].rotation.z=Math.sin(this.phase*1.5)*.08*(i?1:-1);if(this.axe)this.axe.rotation.x=this.action==='heavy'?-1.5:0;
 this.group.position.addScaledVector(this.velocity,dt);this.velocity.multiplyScalar(Math.pow(.08,dt));this.group.position.y=Math.max(0,this.group.position.y);
 }
 hit(damage,knock,from){this.health=Math.max(0,this.health-damage);this.stun=Math.max(this.stun,.46);let dir=this.group.position.clone().sub(from);dir.y=0;if(dir.lengthSq()<.01)dir.set(0,0,1);dir.normalize();this.velocity.addScaledVector(dir,knock);if(knock>5)this.group.position.y=Math.min(1.5,this.group.position.y+.45);if(this.health<=0){this.health=this.maxHealth*.14;this.stun=2.2;this.action='stunned';this.actionTime=2.2;}return this.health;}
}

