  player.action=name;player.actionTime=name==='heavy'?.7:.45;let power=(name==='heavy'?26:13)*player.spec.power,target=rival;let forward=v3(Math.sin(player.group.rotation.y),0,Math.cos(player.group.rotation.y));let did=false;if(target&&player.group.position.distanceTo(target.group.position)<14){let to=target.group.position.clone().sub(player.group.position).normalize();if(forward.dot(to)>.15){target.hit(power,name==='heavy'?7:3,player.group.position);did=true;toast(name==='heavy'?'HEAVY IMPACT':'TITAN STRIKE');}}let b=nearestBuilding(player.group.position,forward,17);if(b){damageBuilding(b,name==='heavy'?48:24);did=true;}if(!did&&name==='heavy')toast('MISS');}
 function fireSpecial(){let start=player.group.position.clone().add(v3(0,5.3,0)),dir=v3(Math.sin(player.group.rotation.y),.04,Math.cos(player.group.rotation.y)).normalize(),end=start.clone().addScaledVector(dir,34);const geo=new THREE.CylinderGeometry(.28,.65,34,12,1,true);const beam=new THREE.Mesh(geo,new THREE.MeshBasicMaterial({color:player.spec.glow,transparent:true,opacity:.8,side:THREE.DoubleSide}));beam.position.copy(start.clone().add(end).multiplyScalar(.5));beam.quaternion.setFromUnitVectors(v3(0,1,0),dir);scene.add(beam);setTimeout(()=>scene.remove(beam),380);if(player.group.position.distanceTo(rival.group.position)<38){let to=rival.group.position.clone().sub(start).normalize();if(dir.dot(to)>.65)rival.hit(36*player.spec.power,11,player.group.position);}let b=nearestBuilding(player.group.position,dir,40);if(b)damageBuilding(b,65);toast(player.spec.kind==='godzilla'||player.spec.kind==='evolved'?'ATOMIC BREATH':'TITAN SPECIAL');}
 function nearestBuilding(pos,dir,range){let best=null,bestDist=range;for(const b of buildings){if(b.dead)continue;let dx=b.x-pos.x,dz=b.z-pos.z,along=dx*dir.x+dz*dir.z,side=Math.abs(dx*dir.z-dz*dir.x);if(along>1&&along<bestDist&&side<(b.w+b.d)*.5+2){best=b;bestDist=along;}}return best;}
